function validate([sentence]) {
  if (typeof sentence !== 'string' || sentence.length < 1 || sentence.length > 500) return 'sentence needs 1 to 500 characters.';
  if (!/^[A-Za-z]+( [A-Za-z]+)*$/.test(sentence)) return 'Use letters only, with single spaces between words and none at the ends.';
  return null;
}

