function generate(rand, size) {
  const large = size === 'large';
  const letters = large ? 'abcdeABCDE' : (rand() < 0.5 ? 'ab' : 'aAbB');
  const pick = () => letters[Math.floor(rand() * letters.length)];
  const target = large ? 480 + Math.floor(rand() * 20) : 1 + Math.floor(rand() * 16);
  const words = [];
  let total = -1;
  for (;;) {
    const len = 1 + Math.floor(rand() * (large ? 9 : 4));
    if (words.length && total + 1 + len > target) break;
    let word = '';
    for (let i = 0; i < len; i++) word += pick();
    words.push(word);
    total += 1 + len;
  }
  if (rand() < 0.6) {
    // Chain the words so the sentence is circular, then sometimes break one spot.
    const m = words.length;
    for (let i = 1; i < m; i++) words[i] = words[i - 1].slice(-1) + words[i].slice(1);
    const last = words[m - 1];
    if (m === 1) words[0] = last.slice(0, -1) + last[0];
    else if (last.length === 1) words[m - 1] = last + words[0][0];
    else words[m - 1] = last.slice(0, -1) + words[0][0];
    if (rand() < 0.3) {
      const k = Math.floor(rand() * m);
      words[k] = pick() + words[k].slice(1);
    }
  }
  return [words.join(' ')];
}
